  "tool": "manage_backends",
  "args": {
    "name": "Earnings Prep Data",
    "url": "http://localhost:7805",
    "operation": "add",
    "widgets_json": {
      "estimate_revisions": {
        "name": "Estimate Revisions",
        "description": "Street estimate revisions by quarter.",
        "endpoint": "/estimate-revisions",
        "type": "table",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "quarter",
              "headerName": "Quarter",
              "cellDataType": "text"
            },
            {
              "field": "eps_estimate",
              "headerName": "EPS Est",
              "cellDataType": "number"
            },
            {
              "field": "revenue_estimate_b",
              "headerName": "Revenue Est ($B)",
              "cellDataType": "number"
            }
          ]
        }
      },
      "earnings_chart": {
        "name": "EPS History",
        "description": "Plotly EPS beat/miss history.",
        "endpoint": "/eps-history",
        "type": "chart",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "raw": true,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ]
      },
      "surprise_metric": {
        "name": "Avg Surprise",
        "description": "Average EPS surprise last 4 quarters.",
        "endpoint": "/avg-surprise",
        "type": "metric",
        "w": 6,
        "h": 4,
        "staleTime": 900000
      }
    }
  }
}

